import React, { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';
import { format } from 'date-fns';
import api from '../services/api';
import { useAuth } from '../context/AuthContext';
import LoadingSpinner from '../components/LoadingSpinner';
import toast from 'react-hot-toast';

const Dashboard = () => {
    const { user } = useAuth();
    const [loading, setLoading] = useState(true);
    const [upcomingEvents, setUpcomingEvents] = useState([]);
    const [pastEvents, setPastEvents] = useState([]);
    const [summary, setSummary] = useState(null);

    useEffect(() => {
        fetchDashboardData();
    }, []);

    const fetchDashboardData = async () => {
        try {
            const [registrationsRes, summaryRes] = await Promise.all([
                api.get('/dashboard/registrations'),
                api.get('/dashboard/summary')
            ]);

            setUpcomingEvents(registrationsRes.data.upcoming);
            setPastEvents(registrationsRes.data.past);
            setSummary(summaryRes.data);
        } catch (error) {
            console.error('Error fetching dashboard data:', error);
            toast.error('Failed to load dashboard data');
        } finally {
            setLoading(false);
        }
    };

    const handleCancel = async (eventId, eventName) => {
        if (window.confirm(`Are you sure you want to cancel registration for "${eventName}"?`)) {
            try {
                await api.delete(`/events/${eventId}/register`);
                toast.success('Registration cancelled successfully');
                fetchDashboardData(); // Refresh data
            } catch (error) {
                const message = error.response?.data?.message || 'Cancellation failed';
                toast.error(message);
            }
        }
    };

    if (loading) return <LoadingSpinner />;

    const containerStyle = {
        maxWidth: '1200px',
        margin: '40px auto',
        padding: '0 20px'
    };

    const titleStyle = {
        fontSize: '2rem',
        color: '#2d3436',
        marginBottom: '10px'
    };

    const welcomeStyle = {
        fontSize: '1.1rem',
        color: '#667eea',
        marginBottom: '30px'
    };

    const summaryGridStyle = {
        display: 'grid',
        gridTemplateColumns: 'repeat(auto-fit, minmax(250px, 1fr))',
        gap: '20px',
        marginBottom: '40px'
    };

    const summaryCardStyle = {
        background: 'white',
        borderRadius: '12px',
        padding: '25px',
        boxShadow: '0 4px 15px rgba(0,0,0,0.1)',
        textAlign: 'center'
    };

    const summaryNumberStyle = {
        fontSize: '2.5rem',
        fontWeight: 'bold',
        color: '#667eea',
        marginBottom: '5px'
    };

    const summaryLabelStyle = {
        fontSize: '1rem',
        color: '#718096'
    };

    const nextEventStyle = {
        background: 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)',
        borderRadius: '12px',
        padding: '30px',
        marginBottom: '40px',
        color: 'white',
        display: 'flex',
        justifyContent: 'space-between',
        alignItems: 'center',
        flexWrap: 'wrap',
        gap: '20px'
    };

    const nextEventTitleStyle = {
        fontSize: '1.2rem',
        opacity: 0.9,
        marginBottom: '10px'
    };

    const nextEventNameStyle = {
        fontSize: '1.8rem',
        fontWeight: 'bold',
        marginBottom: '10px'
    };

    const nextEventDetailsStyle = {
        display: 'flex',
        gap: '20px',
        fontSize: '1rem',
        opacity: 0.9
    };

    const viewButtonStyle = {
        background: 'white',
        color: '#667eea',
        padding: '12px 30px',
        borderRadius: '8px',
        textDecoration: 'none',
        fontWeight: '600',
        transition: 'transform 0.3s ease'
    };

    const sectionTitleStyle = {
        fontSize: '1.5rem',
        color: '#2d3436',
        marginBottom: '20px'
    };

    const eventCardStyle = {
        background: 'white',
        borderRadius: '12px',
        padding: '20px',
        marginBottom: '15px',
        boxShadow: '0 2px 10px rgba(0,0,0,0.05)',
        display: 'flex',
        justifyContent: 'space-between',
        alignItems: 'center',
        flexWrap: 'wrap',
        gap: '20px',
        transition: 'box-shadow 0.3s ease'
    };

    const eventInfoStyle = {
        flex: 1
    };

    const eventNameStyle = {
        fontSize: '1.2rem',
        fontWeight: '600',
        color: '#2d3436',
        marginBottom: '8px'
    };

    const eventMetaStyle = {
        display: 'flex',
        gap: '15px',
        fontSize: '0.9rem',
        color: '#718096',
        flexWrap: 'wrap'
    };

    const eventMetaItemStyle = {
        display: 'flex',
        alignItems: 'center',
        gap: '5px'
    };

    const actionButtonsStyle = {
        display: 'flex',
        gap: '10px'
    };

    const viewDetailButtonStyle = {
        background: '#667eea',
        color: 'white',
        padding: '10px 20px',
        borderRadius: '6px',
        textDecoration: 'none',
        fontSize: '0.9rem',
        transition: 'background 0.3s ease'
    };

    const cancelButtonStyle = {
        background: '#ff4757',
        color: 'white',
        border: 'none',
        padding: '10px 20px',
        borderRadius: '6px',
        cursor: 'pointer',
        fontSize: '0.9rem',
        transition: 'background 0.3s ease'
    };

    const emptyStateStyle = {
        background: 'white',
        borderRadius: '12px',
        padding: '50px',
        textAlign: 'center',
        boxShadow: '0 2px 10px rgba(0,0,0,0.05)'
    };

    const emptyIconStyle = {
        fontSize: '4rem',
        marginBottom: '20px'
    };

    const emptyTextStyle = {
        fontSize: '1.1rem',
        color: '#718096',
        marginBottom: '20px'
    };

    const browseButtonStyle = {
        background: 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)',
        color: 'white',
        padding: '12px 30px',
        borderRadius: '8px',
        textDecoration: 'none',
        display: 'inline-block',
        fontWeight: '600',
        transition: 'transform 0.3s ease'
    };

    return (
        <div style={containerStyle}>
            <h1 style={titleStyle}>Welcome back, {user?.name}!</h1>
            <p style={welcomeStyle}>Here's your event dashboard</p>

            {/* Summary Cards */}
            {summary && (
                <div style={summaryGridStyle}>
                    <div style={summaryCardStyle}>
                        <div style={summaryNumberStyle}>{summary.totalRegistrations}</div>
                        <div style={summaryLabelStyle}>Total Registrations</div>
                    </div>
                    <div style={summaryCardStyle}>
                        <div style={summaryNumberStyle}>{summary.upcomingCount}</div>
                        <div style={summaryLabelStyle}>Upcoming Events</div>
                    </div>
                    <div style={summaryCardStyle}>
                        <div style={summaryNumberStyle}>{summary.pastCount}</div>
                        <div style={summaryLabelStyle}>Past Events</div>
                    </div>
                </div>
            )}

            {/* Next Event */}
            {summary?.nextEvent && (
                <div style={nextEventStyle}>
                    <div>
                        <div style={nextEventTitleStyle}>Your Next Event</div>
                        <div style={nextEventNameStyle}>{summary.nextEvent.name}</div>
                        <div style={nextEventDetailsStyle}>
                            <span>📅 {format(new Date(summary.nextEvent.date), 'MMMM dd, yyyy')}</span>
                            <span>📍 {summary.nextEvent.location.split(',').pop().trim()}</span>
                        </div>
                    </div>
                    <Link
                        to={`/event/${summary.nextEvent._id}`}
                        style={viewButtonStyle}
                        onMouseEnter={(e) => e.target.style.transform = 'scale(1.05)'}
                        onMouseLeave={(e) => e.target.style.transform = 'scale(1)'}
                    >
                        View Details →
                    </Link>
                </div>
            )}

            {/* Upcoming Events */}
            <div style={{ marginBottom: '40px' }}>
                <h2 style={sectionTitleStyle}>
                    Upcoming Events ({upcomingEvents.length})
                </h2>
                {upcomingEvents.length === 0 ? (
                    <div style={emptyStateStyle}>
                        <div style={emptyIconStyle}>📅</div>
                        <p style={emptyTextStyle}>No upcoming events</p>
                        <Link
                            to="/events"
                            style={browseButtonStyle}
                            onMouseEnter={(e) => e.target.style.transform = 'scale(1.05)'}
                            onMouseLeave={(e) => e.target.style.transform = 'scale(1)'}
                        >
                            Browse Events
                        </Link>
                    </div>
                ) : (
                    upcomingEvents.map(({ event }) => (
                        <div 
                            key={event._id} 
                            style={eventCardStyle}
                            onMouseEnter={(e) => e.currentTarget.style.boxShadow = '0 4px 20px rgba(0,0,0,0.1)'}
                            onMouseLeave={(e) => e.currentTarget.style.boxShadow = '0 2px 10px rgba(0,0,0,0.05)'}
                        >
                            <div style={eventInfoStyle}>
                                <h3 style={eventNameStyle}>{event.name}</h3>
                                <div style={eventMetaStyle}>
                                    <span style={eventMetaItemStyle}>📅 {format(new Date(event.date), 'MMM dd, yyyy')}</span>
                                    <span style={eventMetaItemStyle}>⏰ {format(new Date(event.date), 'h:mm a')}</span>
                                    <span style={eventMetaItemStyle}>📍 {event.location.split(',').pop().trim()}</span>
                                    <span style={eventMetaItemStyle}>👤 {event.organizer}</span>
                                </div>
                            </div>
                            <div style={actionButtonsStyle}>
                                <Link
                                    to={`/event/${event._id}`}
                                    style={viewDetailButtonStyle}
                                    onMouseEnter={(e) => e.target.style.background = '#5a67d8'}
                                    onMouseLeave={(e) => e.target.style.background = '#667eea'}
                                >
                                    View
                                </Link>
                                <button
                                    onClick={() => handleCancel(event._id, event.name)}
                                    style={cancelButtonStyle}
                                    onMouseEnter={(e) => e.target.style.background = '#ff6b81'}
                                    onMouseLeave={(e) => e.target.style.background = '#ff4757'}
                                >
                                    Cancel
                                </button>
                            </div>
                        </div>
                    ))
                )}
            </div>

            {/* Past Events */}
            {pastEvents.length > 0 && (
                <div>
                    <h2 style={sectionTitleStyle}>
                        Past Events ({pastEvents.length})
                    </h2>
                    {pastEvents.map(({ event }) => (
                        <div 
                            key={event._id} 
                            style={{...eventCardStyle, opacity: 0.8}}
                        >
                            <div style={eventInfoStyle}>
                                <h3 style={{...eventNameStyle, color: '#718096'}}>{event.name}</h3>
                                <div style={eventMetaStyle}>
                                    <span style={eventMetaItemStyle}>📅 {format(new Date(event.date), 'MMM dd, yyyy')}</span>
                                    <span style={eventMetaItemStyle}>📍 {event.location.split(',').pop().trim()}</span>
                                    <span style={eventMetaItemStyle}>👤 {event.organizer}</span>
                                </div>
                            </div>
                            <Link
                                to={`/event/${event._id}`}
                                style={{...viewDetailButtonStyle, background: '#718096'}}
                                onMouseEnter={(e) => e.target.style.background = '#5a6268'}
                                onMouseLeave={(e) => e.target.style.background = '#718096'}
                            >
                                View
                            </Link>
                        </div>
                    ))}
                </div>
            )}
        </div>
    );
};

export default Dashboard;
